export const OFICINA_HTML = "<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex,nofollow\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@500;600;700;800&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap\"><script>\n/* Conexión de la Oficina con la base propia (reemplaza la base de la página de Claude): lee cada pocos segundos y escribe por la API. */\n(function(){\n  var API='/api/oficina/db/';\n  function req(m,u,b){ return fetch(u,{method:m,credentials:'same-origin',cache:'no-store',headers:b?{'content-type':'application/json'}:undefined,body:b?JSON.stringify(b):undefined}).then(function(r){ if(r.status===401){ location.reload(); throw new Error('401'); } if(!r.ok) throw new Error(String(r.status)); return r.json(); }); }\n  function Q(c){ this.c=c; this.o=''; this.d='desc'; this.l=200; }\n  Q.prototype.orderBy=function(f,d){ this.o=f; this.d=d||'asc'; return this; };\n  Q.prototype.limit=function(n){ this.l=n; return this; };\n  Q.prototype.add=function(obj){ return req('POST',API+this.c,obj); };\n  var subs=[], timer=null, busy=false;\n  function pull(){\n    if(busy) return; busy=true;\n    req('GET','/api/oficina/estado').then(function(j){\n      subs.forEach(function(s){ var docs=j[s.q.c]||[]; s.ok({docs:docs.map(function(d){ return {id:d.id,data:function(){ return d.data; }}; }),metadata:{fromCache:false}}); });\n    }).catch(function(e){ subs.forEach(function(s){ if(s.err) s.err({code:e&&e.message||'error'}); }); }).then(function(){ busy=false; });\n  }\n  function loop(){ pull(); timer=setTimeout(loop,document.hidden?20000:5000); }\n  document.addEventListener('visibilitychange',function(){ if(!document.hidden&&timer){ clearTimeout(timer); loop(); } });\n  Q.prototype.onSnapshot=function(ok,err){\n    var s={q:this,ok:ok,err:err}; subs.push(s);\n    if(!timer) setTimeout(function(){ if(!timer) loop(); },30);\n    return function(){ subs=subs.filter(function(x){ return x!==s; }); };\n  };\n  var db={ collection:function(c){ return new Q(c); }, doc:function(p){ var a=p.split('/'); return { update:function(patch){ return req('PATCH',API+a[0]+'/'+encodeURIComponent(a[1]),patch); } }; } };\n  var user={ isOwner:function(){ return true; }, can:function(){ return true; } };\n  window.claude={ use:function(n){ return Promise.resolve(n==='db'?db:user); } };\n})();\n</script>\n<title>Oficina DEVISEBIT</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap\">\n<style>\n/* Plano de oficina por pisos: arriba lo que espera una decisión, debajo un piso por equipo, cada agente en su escritorio. */\n:root{\n  --bg:#F1F2F4; --surface:#FFFFFF; --surface2:#E7E9ED; --ink:#15171C; --muted:#5A616E; --line:#D3D7DE;\n  --brand:#D7263D; --btn:#15171C; --btn-ink:#FFFFFF;\n  --wall:#E9ECF2; --wall2:#DDE2EB; --flr:#B9A58A; --flr2:#A8947A; --dsk:#8B6B4A; --dsk2:#A9855F; --glass:#CFE6FF; --bld:#2A2F3A;\n  --st-work:#1E6FD9; --st-done:#12935A; --st-wait:#B86E00; --st-err:#D1343B; --st-idle:#8A919E;\n  --f-display:\"Bricolage Grotesque\",\"Helvetica Neue\",Arial,sans-serif;\n  --f-body:\"IBM Plex Sans\",\"Helvetica Neue\",Arial,sans-serif;\n  --f-mono:\"IBM Plex Mono\",ui-monospace,Menlo,Consolas,monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#0D0E11; --surface:#16181D; --surface2:#1F2229; --ink:#ECEEF2; --muted:#9AA1AE; --line:#2B2F38;\n    --brand:#FF5468; --btn:#ECEEF2; --btn-ink:#0D0E11;\n    --wall:#1B2030; --wall2:#232A3D; --flr:#3A3128; --flr2:#2F281F; --dsk:#5A4430; --dsk2:#6E5339; --glass:#1E3350; --bld:#07080B;\n    --st-work:#5AA2FF; --st-done:#3DD598; --st-wait:#F5A524; --st-err:#FF6B72; --st-idle:#7C8493;\n    color-scheme:dark;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#0D0E11; --surface:#16181D; --surface2:#1F2229; --ink:#ECEEF2; --muted:#9AA1AE; --line:#2B2F38;\n  --brand:#FF5468; --btn:#ECEEF2; --btn-ink:#0D0E11;\n  --wall:#1B2030; --wall2:#232A3D; --flr:#3A3128; --flr2:#2F281F; --dsk:#5A4430; --dsk2:#6E5339; --glass:#1E3350; --bld:#07080B;\n  --st-work:#5AA2FF; --st-done:#3DD598; --st-wait:#F5A524; --st-err:#FF6B72; --st-idle:#7C8493;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font:15px/1.45 var(--f-body);padding-block:20px 48px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\n.wrap{max-width:1100px;margin:0 auto;display:flex;flex-direction:column;gap:26px}\nh1,h2,h3{font-family:var(--f-display);margin:0;text-wrap:balance}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--st-work);outline-offset:2px}\n\n/* cabecera */\n.top{display:flex;flex-wrap:wrap;gap:14px 24px;align-items:flex-end;justify-content:space-between}\n.brand{display:flex;flex-direction:column;gap:4px;min-width:0}\n.kicker{font:500 12px var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;gap:8px}\n.kicker::before{content:\"\";width:8px;height:8px;background:var(--brand);border-radius:2px}\nh1{font-size:clamp(28px,6vw,40px);line-height:1.05;font-weight:700}\n.counts{display:flex;flex-wrap:wrap;gap:8px}\n.pill{display:flex;align-items:center;gap:8px;padding:7px 12px;border:1px solid var(--line);background:var(--surface);border-radius:999px;font:500 13px var(--f-mono)}\n.pill b{font-size:15px}\n.dot{width:9px;height:9px;border-radius:50%;background:var(--c,var(--st-idle));flex:none}\n.sync{font:400 12px var(--f-mono);color:var(--muted)}\n.sync[data-bad=\"1\"]{color:var(--st-wait)}\n\n/* bloques */\n.block{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:16px;display:flex;flex-direction:column;gap:12px}\n.block h2{font-size:19px;font-weight:600}\n.sub{color:var(--muted);font-size:13px;margin:0}\n.attn{border-color:var(--st-wait)}\n.attn-list{display:flex;flex-direction:column;gap:8px}\n.attn-item{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;background:var(--surface2);border-radius:8px}\n.attn-item .dot{margin-top:6px}\n.attn-item p{margin:0;min-width:0;overflow-wrap:anywhere}\n.attn-item small{display:block;color:var(--muted);font:400 12px var(--f-mono);margin-top:2px}\n.calm{color:var(--muted);margin:0}\n\n/* órdenes */\n.compose{display:flex;flex-direction:column;gap:8px}\ntextarea{width:100%;min-height:76px;resize:vertical;background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:10px 12px}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.btn{background:var(--btn);color:var(--btn-ink);border:0;border-radius:8px;padding:9px 16px;font-weight:600}\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\n.btn[disabled]{opacity:.45;cursor:not-allowed}\n.orders{display:flex;flex-direction:column;gap:10px}\n.order{border:1px solid var(--line);border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:8px;min-width:0}\n.order p{margin:0;overflow-wrap:anywhere}\n.chip{align-self:flex-start;font:500 11px var(--f-mono);letter-spacing:.04em;text-transform:uppercase;padding:3px 8px;border-radius:999px;border:1px solid var(--c,var(--line));color:var(--c,var(--muted))}\n.reparto{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px;font-size:14px}\n.reparto b{font-weight:600}\n.meta{font:400 12px var(--f-mono);color:var(--muted)}\n\n/* edificio: cada piso es una sala con escritorios */\n.building{background:var(--bld);border-radius:14px;padding:8px;display:flex;flex-direction:column;gap:6px;box-shadow:0 10px 30px rgba(0,0,0,.18)}\n.floor{display:grid;grid-template-columns:44px 1fr;gap:0;border-radius:8px;overflow:hidden;background:var(--wall)}\n.plate{background:var(--bld);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font:600 11px var(--f-mono);padding:6px 0;border-right:2px solid var(--brand)}\n.plate b{font:700 24px var(--f-display);line-height:1}\n.room{position:relative;min-width:0;background:\n  linear-gradient(var(--wall) 0 72%,var(--flr) 72% 100%);padding:10px 10px 0}\n.room::before{content:\"\";position:absolute;left:0;right:0;top:0;height:72%;background:\n  repeating-linear-gradient(90deg,transparent 0 86px,var(--wall2) 86px 88px);opacity:.7;pointer-events:none}\n.room::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:28%;background:repeating-linear-gradient(90deg,var(--flr2) 0 2px,transparent 2px 60px);opacity:.5;pointer-events:none}\n.rhead{position:relative;z-index:1;display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin-bottom:4px}\n.rhead h2{font-size:18px;font-weight:700}\n.rhead .fc{margin-left:auto;font:500 11px var(--f-mono);color:var(--muted);background:var(--surface);padding:2px 8px;border-radius:999px;border:1px solid var(--line)}\n.desks{position:relative;z-index:1;display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:0 6px}\n.wk{all:unset;box-sizing:border-box;cursor:pointer;position:relative;display:flex;flex-direction:column;align-items:center;min-width:0;padding-top:4px}\n.wk:focus-visible{outline:2px solid var(--st-work);outline-offset:-2px;border-radius:8px}\n.bub{position:relative;max-width:100%;min-height:34px;display:flex;align-items:center;justify-content:center;text-align:center;font-size:11.5px;line-height:1.25;background:var(--surface);color:var(--ink);border:1.5px solid var(--c);border-radius:10px;padding:5px 8px;overflow-wrap:anywhere;box-shadow:0 2px 0 rgba(0,0,0,.08)}\n.bub::after{content:\"\";position:absolute;left:50%;bottom:-6px;width:9px;height:9px;background:var(--surface);border-right:1.5px solid var(--c);border-bottom:1.5px solid var(--c);transform:translateX(-50%) rotate(45deg)}\n.bub span{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.who{position:relative;width:100%;height:122px;margin-top:6px}\n.av2{position:absolute;left:50%;bottom:48px;width:62px;height:62px;margin-left:-31px;z-index:1;transform-origin:50% 100%}\n.av2 svg{width:62px;height:62px;display:block;overflow:visible}\n.dk{position:absolute;left:6%;right:6%;bottom:0;height:34px;z-index:3}\n.dk .top{position:absolute;left:0;right:0;top:0;height:11px;background:var(--dsk2);border-radius:4px 4px 2px 2px;box-shadow:0 2px 0 rgba(0,0,0,.18)}\n.dk .leg{position:absolute;left:8%;right:8%;top:11px;bottom:0;background:var(--dsk);border-radius:0 0 3px 3px}\n.mon{position:absolute;left:50%;bottom:30px;width:40px;height:22px;margin-left:-20px;background:#1b1e25;border-radius:4px;border:2px solid #2d313b;z-index:2;overflow:hidden;box-shadow:0 0 0 0 var(--c)}\n.mon::after{content:\"\";position:absolute;left:50%;bottom:-6px;width:8px;height:4px;margin-left:-4px;background:#2d313b}\n.mon i{position:absolute;left:4px;height:3px;border-radius:2px;background:var(--c);opacity:.35}\n.mon i:nth-child(1){top:3px;width:24px}.mon i:nth-child(2){top:8px;width:16px}.mon i:nth-child(3){top:13px;width:28px}\n.tag{position:relative;z-index:4;margin-top:-2px;max-width:100%;text-align:center;background:var(--surface);border:1px solid var(--line);border-bottom:3px solid var(--c);border-radius:6px;padding:3px 8px 4px;min-width:0}\n.tag b{display:block;font:600 12px var(--f-display);line-height:1.15;overflow-wrap:anywhere}\n.tag small{display:block;font:500 9.5px var(--f-mono);letter-spacing:.05em;text-transform:uppercase;color:var(--c)}\n.badge{position:absolute;z-index:5;right:14%;top:-6px;width:20px;height:20px;border-radius:50%;background:var(--c);color:#fff;display:none;align-items:center;justify-content:center;font:700 12px var(--f-mono)}\n.wk[data-st=\"waiting_user\"] .badge,.wk[data-st=\"error\"] .badge,.wk[data-st=\"done\"] .badge{display:flex}\n.zz{position:absolute;z-index:5;left:58%;top:6px;font:700 13px var(--f-display);color:var(--muted);display:none}\n.wk[data-st=\"idle\"] .zz,.wk[data-st=\"none\"] .zz{display:block;animation:zz 3s ease-in-out infinite}\n.wk[data-st=\"idle\"] .av2,.wk[data-st=\"none\"] .av2{opacity:.72;animation:breathe 4s ease-in-out infinite}\n.wk[data-st=\"none\"] .av2{filter:grayscale(.8)}\n.wk[data-st=\"working\"] .av2{animation:type .55s ease-in-out infinite}\n.wk[data-st=\"working\"] .mon{animation:glow 1.4s ease-in-out infinite}\n.wk[data-st=\"working\"] .mon i{opacity:.9;animation:ln 1.1s steps(2) infinite}\n.wk[data-st=\"working\"] .mon i:nth-child(2){animation-delay:.3s}.wk[data-st=\"working\"] .mon i:nth-child(3){animation-delay:.6s}\n.wk[data-st=\"waiting_user\"] .av2{animation:hop 1s ease-in-out infinite}\n.wk[data-st=\"waiting_user\"] .bub{animation:pulseb 1.6s ease-in-out infinite}\n.wk[data-st=\"error\"] .av2{animation:shake .4s linear infinite}\n.wk[data-st=\"done\"] .av2{animation:hop 2.4s ease-in-out infinite}\n.wk:hover .tag{border-color:var(--c)}\n@keyframes type{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px) rotate(-1.5deg)}}\n@keyframes hop{0%,100%{transform:translateY(0)}40%{transform:translateY(-9px)}}\n@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-2px)}75%{transform:translateX(2px)}}\n@keyframes breathe{0%,100%{transform:scaleY(1)}50%{transform:scaleY(.97)}}\n@keyframes glow{0%,100%{box-shadow:0 0 0 0 transparent}50%{box-shadow:0 0 12px 2px var(--c)}}\n@keyframes ln{0%{width:8px}100%{width:28px}}\n@keyframes zz{0%,100%{transform:translateY(0);opacity:.4}50%{transform:translateY(-7px);opacity:1}}\n@keyframes pulseb{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}\n@media (prefers-reduced-motion:reduce){.wk *,.wk .av2,.wk .mon,.wk .bub{animation:none!important}}\n@media (max-width:420px){.floor{grid-template-columns:34px 1fr}.plate b{font-size:19px}.room{padding:8px 6px 0}}\n\n/* actividad */\n.feed{display:flex;flex-direction:column}\n.ev{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:baseline;padding:8px 0;border-bottom:1px solid var(--line)}\n.ev:last-child{border-bottom:0}\n.ev span:nth-child(2){min-width:0;overflow-wrap:anywhere}\n.ev .t{font:400 12px var(--f-mono);color:var(--muted);white-space:nowrap}\n\n/* leyenda */\n.legend{display:flex;flex-wrap:wrap;gap:6px 16px;font:400 12px var(--f-mono);color:var(--muted)}\n.legend span{display:flex;align-items:center;gap:6px}\n\n/* hoja de detalle */\n.sheet{position:fixed;inset:0;z-index:20;display:flex;align-items:flex-end;justify-content:center;background:color-mix(in srgb,var(--bg) 70%,transparent)}\n.sheet[hidden]{display:none}\n.sheet-card{width:100%;max-width:640px;max-height:86%;overflow:auto;background:var(--surface);border:1px solid var(--line);border-radius:14px 14px 0 0;padding:18px max(16px,env(safe-area-inset-left,0px)) calc(18px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:12px;box-shadow:0 -8px 30px rgba(0,0,0,.18)}\n.sheet-head{display:flex;gap:12px;align-items:center;justify-content:space-between}\n.sheet-head h3{font-size:22px}\n.sheet-card h4{margin:0;font:500 12px var(--f-mono);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.sheet-card ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px;font-size:14px}\n.pform{display:flex;flex-direction:column;gap:8px;border-top:1px solid var(--line);padding-top:12px}\n.pform[hidden]{display:none}\nselect,input[type=text]{background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:9px 10px;width:100%}\n.err{color:var(--st-err);font-size:13px;margin:0}\n\n/* escena 3D */\n:root{--sky1:#8ec9ff;--sky2:#eaf5ff}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){--sky1:#05070f;--sky2:#1b2347}}\n:root[data-theme=\"dark\"]{--sky1:#05070f;--sky2:#1b2347}\n.stage{padding:12px;gap:10px}\n.stage-bar{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;justify-content:space-between}\n.stage-bar h2{font-size:19px}\n.btn.sm{padding:6px 12px;font-size:13px;font-weight:500}\n.cv{position:relative;height:clamp(480px,130vw,720px);border-radius:12px;overflow:hidden;background:linear-gradient(var(--sky1),var(--sky2))}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .cv{background:radial-gradient(1.5px 1.5px at 12% 18%,#fff8,transparent),radial-gradient(1.5px 1.5px at 70% 10%,#fff8,transparent),radial-gradient(1px 1px at 40% 30%,#fff8,transparent),radial-gradient(1.5px 1.5px at 88% 40%,#fff8,transparent),radial-gradient(1px 1px at 25% 55%,#fff6,transparent),linear-gradient(var(--sky1),var(--sky2))}}\n:root[data-theme=\"dark\"] .cv{background:radial-gradient(1.5px 1.5px at 12% 18%,#fff8,transparent),radial-gradient(1.5px 1.5px at 70% 10%,#fff8,transparent),radial-gradient(1px 1px at 40% 30%,#fff8,transparent),radial-gradient(1.5px 1.5px at 88% 40%,#fff8,transparent),linear-gradient(var(--sky1),var(--sky2))}\n.cv canvas{display:block;touch-action:pan-y;cursor:grab}\n.chips{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px;scrollbar-width:thin}\n.chip3{all:unset;cursor:pointer;flex:none;white-space:nowrap;padding:7px 12px;border:1px solid var(--line);border-radius:999px;background:var(--surface2);font:500 13px var(--f-body)}\n.chip3:focus-visible{outline:2px solid var(--st-work);outline-offset:2px}\n.chip3[aria-pressed=\"true\"]{background:var(--btn);color:var(--btn-ink);border-color:var(--btn)}\n.chip3 b{font:500 11px var(--f-mono);opacity:.8}\n</style>\n<style>\n#chips{display:none!important}\n.side,.team,.feedbox,.drawer{--surface:#171A21;--surface2:#222631;--ink:#ECEEF2;--muted:#9AA1AE;--line:#2B2F38;--bg:#0D0E11;--btn:#ECEEF2;--btn-ink:#0D0E11;background:#171A21;color:#ECEEF2;border-color:#2B2F38}\n.side .btn.ghost,.drawer .btn.ghost{color:#ECEEF2}\n/* ===== Rediseño: una sala grande, pisos a la izquierda, equipo a la derecha ===== */\nhtml,body{height:100%}\nbody{padding:0;margin:0;background:var(--bg)}\n.app{height:100dvh;display:flex;flex-direction:column;gap:8px;padding:10px 12px 12px;max-width:none;margin:0}\n.bar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;justify-content:space-between}\n.logo{display:flex;align-items:center;gap:10px}\n.mk{width:34px;height:34px;border-radius:10px;background:var(--brand);color:#fff;display:grid;place-items:center;font:800 18px var(--f-display)}\n.lt b{display:block;font:700 18px/1.1 var(--f-display)}.lt small{color:var(--muted);font:500 11px var(--f-mono);letter-spacing:.08em;text-transform:uppercase}\n.live{display:inline-flex;align-items:center;gap:6px;font:500 11px var(--f-mono);color:var(--st-done);border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:3px 10px}\n.live i{width:8px;height:8px;border-radius:50%;background:var(--st-done);animation:lv 1.6s infinite}\n@keyframes lv{50%{opacity:.35}}\n.counts{display:flex;gap:6px;flex-wrap:wrap}\n.pill{padding:5px 10px;font-size:12px}.pill b{font-size:14px}\n.tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:999px;overflow:hidden;background:var(--surface)}\n.seg button{border:0;background:transparent;padding:6px 12px;font:500 13px var(--f-body);color:var(--muted)}\n.seg button[aria-pressed=\"true\"]{background:var(--ink);color:var(--bg)}\na.btn{text-decoration:none;display:inline-flex;align-items:center}\n.grid{flex:1;min-height:0;display:grid;grid-template-columns:280px minmax(0,1fr) 340px;gap:10px}\n.side,.team{overflow:auto;background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:14px;display:flex;flex-direction:column;gap:10px;min-height:0}\n.sh{font:600 12px var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n.pisos{display:flex;flex-direction:column;gap:6px}\n.piso{display:grid;grid-template-columns:30px 1fr auto;gap:10px;align-items:center;text-align:left;background:transparent;border:1px solid transparent;border-radius:12px;padding:8px 10px}\n.piso:hover{background:var(--surface2)}\n.piso[aria-pressed=\"true\"]{background:var(--surface2);border-color:var(--line)}\n.piso .no{width:30px;height:30px;border-radius:9px;background:var(--ink);color:var(--bg);display:grid;place-items:center;font:700 14px var(--f-mono)}\n.piso[aria-pressed=\"true\"] .no{background:var(--brand);color:#fff}\n.piso .nm{font-weight:600;font-size:14px;line-height:1.2}.piso .nm small{display:block;color:var(--muted);font:400 11px var(--f-mono);margin-top:2px}\n.piso .ct{font:600 12px var(--f-mono);color:var(--muted);display:flex;gap:4px;align-items:center}\n.piso .ct i{width:8px;height:8px;border-radius:50%;background:var(--st-work)}\n.grp{border-top:1px solid var(--line);padding-top:8px}\n.grp summary{cursor:pointer;font-weight:600;font-size:14px;display:flex;justify-content:space-between;align-items:center;list-style:none}\n.grp summary::-webkit-details-marker{display:none}\n.grp summary b{background:var(--surface2);border-radius:999px;padding:1px 9px;font:600 12px var(--f-mono)}\n.grp[open] summary{margin-bottom:8px}\n#attn h2{display:none}#attn{border:0!important;padding:0!important;background:none!important}\n#attn .attn-item{font-size:13px}\n.mini{display:flex;flex-direction:column;gap:6px}.mini div{display:flex;justify-content:space-between;gap:8px;font-size:13px;padding:6px 8px;background:var(--surface2);border-radius:8px}.mini small{color:var(--muted);font:400 11px var(--f-mono);text-align:right}\n.mid{position:relative;min-height:0;min-width:0}\n.stage{position:absolute;inset:0;padding:0!important;border:1px solid var(--line)!important;border-radius:16px;overflow:hidden;background:var(--surface)}\n.stage .cv{height:100%!important;border-radius:0}\n.feedbox{position:absolute;left:12px;bottom:12px;width:min(320px,calc(100% - 24px));background:color-mix(in srgb,var(--surface) 90%,transparent);backdrop-filter:blur(8px);border:1px solid var(--line);border-radius:14px;padding:8px 12px;max-height:190px;overflow:hidden}\n.feedbox h3{font:600 11px var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:2px}\n.feedbox .ev{padding:4px 0;font-size:12px;grid-template-columns:auto 1fr auto}.feedbox .ev:nth-child(n+6){display:none}\n.team .th{display:flex;align-items:center;gap:10px}\n.team .th .no{width:38px;height:38px;border-radius:11px;background:var(--brand);color:#fff;display:grid;place-items:center;font:700 16px var(--f-mono);flex:none}\n.team .th h2{font-size:19px;line-height:1.15}.team .th small{display:block;color:var(--muted);font:400 12px var(--f-mono)}\n.team .okb{margin-left:auto;background:color-mix(in srgb,var(--st-done) 16%,transparent);color:var(--st-done);border-radius:999px;padding:3px 10px;font:600 12px var(--f-mono);white-space:nowrap}\n.team .resp{background:var(--ink);color:var(--bg);border-radius:12px;padding:8px 12px;font-size:13px}.team .resp b{display:block}\n.mrows{display:flex;flex-direction:column;gap:6px}\n.mrow{display:grid;grid-template-columns:40px 1fr auto;gap:10px;align-items:center;text-align:left;background:var(--surface2);border:1px solid transparent;border-radius:12px;padding:8px 10px}\n.mrow:hover{border-color:var(--line)}\n.mrow .av{width:40px;height:40px;border-radius:50%;background:var(--surface);border:2px solid var(--c);display:grid;place-items:center;padding:3px}\n.mrow .av svg{width:100%;height:100%}\n.mrow .tx b{display:block;font-size:14px;line-height:1.2}.mrow .tx small{display:block;color:var(--muted);font-size:12px;line-height:1.3;overflow-wrap:anywhere}\n.mrow .stc{font:600 11px var(--f-mono);color:var(--c);display:flex;gap:5px;align-items:center;white-space:nowrap}.mrow .stc i{width:8px;height:8px;border-radius:50%;background:var(--c)}\n.drawer{position:fixed;top:0;right:0;bottom:0;width:min(440px,100%);z-index:30;background:var(--surface);border-left:1px solid var(--line);box-shadow:-12px 0 40px rgba(0,0,0,.18);padding:16px;overflow:auto;display:flex;flex-direction:column;gap:12px}\n.drawer[hidden]{display:none}\n.dhead{display:flex;justify-content:space-between;align-items:center;gap:8px}.dhead h2{font-size:20px}\n.dh3{font:600 12px var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n.drawer .compose textarea{min-height:110px}\n.drawer .row{flex-wrap:wrap}\n.legend{margin-top:auto;font-size:11px}\n@media (max-width:1000px){\n  html,body{height:auto}\n  .app{height:auto;min-height:100dvh}\n  .bar{position:sticky;top:0;z-index:15;background:var(--bg);padding-block:6px}\n  .grid{display:flex;flex-direction:column}\n  .side{display:contents}\n  .sh{display:none}\n  .pisos{order:0;flex-direction:row;overflow-x:auto;gap:6px;padding-bottom:4px}\n  .piso{flex:none;grid-template-columns:26px auto auto;padding:6px 10px;border-color:var(--line);background:var(--surface)}\n  .piso .nm small{display:none}.piso .no{width:26px;height:26px;font-size:12px}\n  .mid{order:1;height:min(58vh,480px);flex:none}\n  .team{order:2;overflow:visible}\n  .grp{order:3;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px}\n  .legend{order:4;margin:0}\n  .counts{width:100%;overflow-x:auto;flex-wrap:nowrap}.pill{flex:none}\n  .tools{width:100%}\n  .feedbox{max-height:96px}.feedbox .ev:nth-child(n+3){display:none}\n}\n</style>\n\n\n<div class=\"app\" id=\"app\">\n  <header class=\"bar\">\n    <div class=\"logo\"><span class=\"mk\" aria-hidden=\"true\">D</span><div class=\"lt\"><b>Oficina</b><small>DEVISEBIT</small></div><span class=\"live\"><i></i>En vivo</span></div>\n    <div class=\"counts\" id=\"counts\" aria-live=\"polite\"></div>\n    <div class=\"tools\">\n      <div class=\"seg\" role=\"group\" aria-label=\"Vista\">\n        <button type=\"button\" id=\"vday\" aria-pressed=\"true\">Día</button><button type=\"button\" id=\"vnight\" aria-pressed=\"false\">Noche</button><button type=\"button\" id=\"vtour\" aria-pressed=\"false\">Tour</button>\n      </div>\n      <a class=\"btn ghost sm\" href=\"/api/oficina/organigrama\" id=\"orglink\">Organigrama</a>\n      <button class=\"btn sm\" id=\"jefebtn\" type=\"button\">Hablar con el jefe</button>\n    </div>\n  </header>\n  <div class=\"sync\" id=\"sync\">Conectando con la base…</div>\n  <div class=\"grid\">\n    <aside class=\"side\" id=\"side\">\n      <h2 class=\"sh\">Pisos</h2>\n      <div class=\"pisos\" id=\"pisos\" role=\"group\" aria-label=\"Elegir piso\"></div>\n      <details class=\"grp\" id=\"g-esp\" open><summary>Esperando por mí <b id=\"n-esp\">0</b></summary><div id=\"attn\" aria-live=\"polite\"></div></details>\n      <details class=\"grp\" id=\"g-fin\"><summary>Terminados <b id=\"n-fin\">0</b></summary><div id=\"fin\"></div></details>\n      <details class=\"grp\" id=\"g-rut\"><summary>Rutinas <b id=\"n-rut\">0</b></summary><div id=\"rut\"></div></details>\n      <div class=\"legend\" id=\"legend\"></div>\n    </aside>\n    <main class=\"mid\">\n      <section class=\"stage\" id=\"stage\" aria-label=\"Oficina en 3D\" hidden>\n        <div class=\"chips only3d\" id=\"chips\" hidden></div>\n        <div class=\"cv only3d\" id=\"cv\"></div>\n        <div class=\"feedbox\"><h3>Actividad</h3><div class=\"feed\" id=\"feed\"></div></div>\n        <button class=\"btn ghost sm\" id=\"viewtgl\" type=\"button\" hidden>Ver como lista</button>\n      </section>\n    </main>\n    <aside class=\"team\" id=\"team\" aria-live=\"polite\"></aside>\n  </div>\n  <section class=\"drawer\" id=\"drawer\" hidden role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ord-h\">\n    <div class=\"dhead\"><h2 id=\"ord-h\">Hablar con el jefe</h2><button class=\"btn ghost sm\" id=\"drawerx\" type=\"button\">Cerrar</button></div>\n    <p class=\"sub\">Decilo una vez: escribilo, dictalo, llamalo por voz o mandá un audio por WhatsApp. El jefe propone quién hace qué y vos aprobás.</p>\n    <div class=\"compose\">\n      <label for=\"ordtxt\" class=\"meta\">Nueva orden</label>\n      <textarea id=\"ordtxt\" placeholder=\"Ej.: Armá una propuesta para la licitación de PAMI y avisale a Bárbara que prepare la demo.\"></textarea>\n      <div class=\"row\">\n        <button class=\"btn\" id=\"ordsend\" type=\"button\">Enviar al jefe</button>\n        <button class=\"btn ghost\" id=\"ordmic\" type=\"button\" aria-pressed=\"false\" hidden>Dictar</button>\n        <button class=\"btn\" id=\"ordcall\" type=\"button\" aria-pressed=\"false\" hidden>Llamar (voz)</button>\n        <span class=\"err\" id=\"orderr\" hidden></span>\n      </div>\n    </div>\n    <h3 class=\"dh3\">Órdenes</h3>\n    <div class=\"orders\" id=\"orders\"></div>\n  </section>\n  <div id=\"floors\" hidden></div>\n</div>\n\n<div class=\"sheet\" id=\"sheet\" hidden>\n  <div class=\"sheet-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"sh-title\">\n    <div class=\"sheet-head\">\n      <h3 id=\"sh-title\"></h3>\n      <button class=\"btn ghost\" id=\"shclose\" type=\"button\">Cerrar</button>\n    </div>\n    <div id=\"shbody\"></div>\n    <div class=\"pform\" id=\"pform\" hidden>\n      <h4>Actualizar su estado</h4>\n      <label class=\"meta\" for=\"pst\">Estado</label>\n      <select id=\"pst\">\n        <option value=\"working\">trabajando</option>\n        <option value=\"waiting_user\">te necesita</option>\n        <option value=\"done\">terminó</option>\n        <option value=\"idle\">en reposo</option>\n        <option value=\"error\">bloqueado</option>\n      </select>\n      <label class=\"meta\" for=\"pnom\">Nombre</label>\n      <div class=\"row\"><input type=\"text\" id=\"pnom\" maxlength=\"40\"><button class=\"btn ghost\" id=\"pnsave\" type=\"button\">Cambiar nombre</button></div>\n      <label class=\"meta\" for=\"ppaso\">En qué está (máx. 60 caracteres)</label>\n      <input type=\"text\" id=\"ppaso\" maxlength=\"60\" placeholder=\"Ej.: preparando la demo de WhatsApp\">\n      <div class=\"row\"><button class=\"btn\" id=\"psave\" type=\"button\">Guardar estado</button><span class=\"err\" id=\"perr\" hidden></span></div>\n    </div>\n  </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n<script>\nconst ST={\n  working:{t:'trabajando',c:'var(--st-work)'},\n  done:{t:'terminó',c:'var(--st-done)'},\n  idle:{t:'en reposo',c:'var(--st-idle)'},\n  waiting_user:{t:'te necesita',c:'var(--st-wait)'},\n  error:{t:'error',c:'var(--st-err)'},\n  none:{t:'sin reporte',c:'var(--st-idle)'}\n};\nconst OST={\n  nueva:{t:'espera al jefe',c:'var(--st-idle)'},\n  propuesta:{t:'para tu OK',c:'var(--st-wait)'},\n  aprobada:{t:'aprobada',c:'var(--st-work)'},\n  repartida:{t:'repartida',c:'var(--st-done)'},\n  rechazada:{t:'rechazada',c:'var(--st-idle)'},\n  hecha:{t:'hecha',c:'var(--st-done)'}\n};\nconst PISOS={6:'Academia Educativa',5:'Dirección y gabinete',4:'Comercial y licitaciones',3:'Contenido y redes',2:'Administración y finanzas',1:'Sistemas y desarrollo',0:'Equipo'};\nconst CARGO={6:'Responsable de Academia',5:'Jefa de gabinete',4:'Responsable de Comercial',3:'Responsable de Contenido',2:'Responsable de Administración (solo Julio)',1:'Responsable de Sistemas'};\nfunction respDe(p){ const r=S.agentes.find(a=>a.tipo==='persona'&&a.piso===p); return r?(CARGO[p]||'Responsable')+': '+r.nombre:(CARGO[p]||'Responsable')+': a definir'; }\nconst S={agentes:[],eventos:[],ordenes:[],tareas:[],got:{},db:null,user:null,canWrite:false,sel:null};\nconst $=id=>document.getElementById(id);\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\nfunction ago(iso){\n  const t=Date.parse(iso); if(!t) return '';\n  const m=Math.max(0,Math.round((Date.now()-t)/60000));\n  if(m<1) return 'recién';\n  if(m<60) return 'hace '+m+' min';\n  const h=Math.round(m/60); if(h<24) return 'hace '+h+' h';\n  const d=Math.round(h/24); return 'hace '+d+' d';\n}\n\nfunction avatar(l){\n  l=l||{}; const c=l.color||'#959595', f=l.forma||'sphere', a=l.acc||'none';\n  const dark=/^#?(0{6}|1[0-9a-f]{5})$/i.test(c.replace('#',''));\n  const eye=dark?'#fff':'#111';\n  let b='';\n  if(f==='rsquare') b='<rect x=\"10\" y=\"12\" width=\"44\" height=\"44\" rx=\"13\" fill=\"'+c+'\"/>';\n  else if(f==='star') b='<polygon points=\"32,6 39,24 58,26 43,39 48,58 32,48 16,58 21,39 6,26 25,24\" fill=\"'+c+'\" stroke=\"'+c+'\" stroke-width=\"3\" stroke-linejoin=\"round\"/>';\n  else if(f==='hexagon') b='<polygon points=\"32,8 54,20 54,46 32,58 10,46 10,20\" fill=\"'+c+'\" stroke=\"'+c+'\" stroke-width=\"3\" stroke-linejoin=\"round\"/>';\n  else if(f==='triangle') b='<polygon points=\"32,9 57,55 7,55\" fill=\"'+c+'\" stroke=\"'+c+'\" stroke-width=\"4\" stroke-linejoin=\"round\"/>';\n  else if(f==='pill') b='<rect x=\"17\" y=\"6\" width=\"30\" height=\"52\" rx=\"15\" fill=\"'+c+'\"/>';\n  else if(f==='drop') b='<path d=\"M32 6C45 22 53 33 53 43a21 21 0 0 1-42 0C11 33 19 22 32 6Z\" fill=\"'+c+'\"/>';\n  else if(f==='flower') b='<g fill=\"'+c+'\"><circle cx=\"32\" cy=\"17\" r=\"12\"/><circle cx=\"32\" cy=\"47\" r=\"12\"/><circle cx=\"17\" cy=\"32\" r=\"12\"/><circle cx=\"47\" cy=\"32\" r=\"12\"/><circle cx=\"32\" cy=\"32\" r=\"14\"/></g>';\n  else if(f==='cloud') b='<g fill=\"'+c+'\"><circle cx=\"21\" cy=\"38\" r=\"13\"/><circle cx=\"34\" cy=\"29\" r=\"15\"/><circle cx=\"46\" cy=\"39\" r=\"12\"/><rect x=\"21\" y=\"38\" width=\"25\" height=\"13\"/></g>';\n  else b='<circle cx=\"32\" cy=\"33\" r=\"23\" fill=\"'+c+'\"/>';\n  let face='<circle cx=\"25\" cy=\"34\" r=\"2.6\" fill=\"'+eye+'\"/><circle cx=\"39\" cy=\"34\" r=\"2.6\" fill=\"'+eye+'\"/>';\n  let acc='';\n  if(a==='glasses'){ face=''; acc='<g fill=\"none\" stroke=\"'+eye+'\" stroke-width=\"2.6\"><circle cx=\"24\" cy=\"34\" r=\"6.5\"/><circle cx=\"40\" cy=\"34\" r=\"6.5\"/><line x1=\"30.5\" y1=\"34\" x2=\"33.5\" y2=\"34\"/></g>'; }\n  else if(a==='antenna') acc='<line x1=\"32\" y1=\"9\" x2=\"32\" y2=\"2\" stroke=\"'+eye+'\" stroke-width=\"2.4\"/><circle cx=\"32\" cy=\"3\" r=\"3\" fill=\"'+eye+'\"/>';\n  else if(a==='bow') acc='<g fill=\"'+eye+'\"><polygon points=\"32,52 21,46 21,58\"/><polygon points=\"32,52 43,46 43,58\"/></g>';\n  else if(a==='stem') acc='<path d=\"M32 10C32 4 38 2 42 3C41 8 37 11 32 10Z\" fill=\"'+eye+'\"/>';\n  return '<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\">'+b+face+acc+'</svg>';\n}\n\n/* estado más reciente de cada agente */\nfunction latest(){\n  const m={};\n  for(const e of S.eventos){ const k=e.agente; if(k && !m[k]) m[k]=e; } // eventos vienen del más nuevo al más viejo\n  return m;\n}\nfunction stateOf(ag,lat){\n  const e=lat[ag.id];\n  if(!e) return {k:'none',paso:'',at:''};\n  const k=ST[e.estado]?e.estado:'none';\n  return {k,paso:e.paso||'',at:e.at||''};\n}\nfunction tareasDe(id){ return S.tareas.filter(t=>t.agente===id && t.estado!=='hecha'); }\nfunction nombreAg(id){ const a=S.agentes.find(x=>x.id===id); return a?a.nombre:id; }\n\nfunction renderCounts(lat){\n  const c={working:0,waiting_user:0,error:0,rest:0};\n  for(const a of S.agentes){ const k=stateOf(a,lat).k; if(k==='working')c.working++; else if(k==='waiting_user')c.waiting_user++; else if(k==='error')c.error++; else c.rest++; }\n  const p=(n,l,col)=>'<div class=\"pill\"><span class=\"dot\" style=\"--c:'+col+'\"></span><b>'+n+'</b> '+l+'</div>';\n  $('counts').innerHTML=p(c.working,'trabajando',ST.working.c)+p(c.waiting_user,'te necesitan',ST.waiting_user.c)+p(c.error,'errores',ST.error.c)+p(c.rest,'en reposo',ST.idle.c);\n}\n\nfunction renderAttn(lat){\n  const items=[];\n  for(const a of S.agentes){\n    const s=stateOf(a,lat);\n    if(s.k==='waiting_user'||s.k==='error') items.push('<div class=\"attn-item\"><span class=\"dot\" style=\"--c:'+ST[s.k].c+'\"></span><p><b>'+esc(a.nombre)+'</b>: '+esc(s.paso||ST[s.k].t)+'<small>'+ST[s.k].t+' · '+ago(s.at)+'</small></p></div>');\n  }\n  for(const o of S.ordenes){\n    if(o.estado==='propuesta') items.push('<div class=\"attn-item\"><span class=\"dot\" style=\"--c:'+OST.propuesta.c+'\"></span><p>Propuesta del jefe para aprobar: <b>'+esc(String(o.texto||'').slice(0,90))+'</b><small>abajo, en Órdenes</small></p></div>');\n  }\n  $('attn').classList.toggle('attn',items.length>0);\n  $('attn').innerHTML='<h2 id=\"attn-h\">'+(items.length?'Necesita de vos':'Nada espera tu decisión')+'</h2>'+\n    (items.length?'<div class=\"attn-list\">'+items.join('')+'</div>':'<p class=\"calm\">Cuando un agente te necesite o falle algo, aparece acá arriba.</p>');\n}\n\nfunction renderOrders(){\n  const box=$('orders');\n  if(!S.ordenes.length){ box.innerHTML='<p class=\"calm\">Todavía no diste ninguna orden.</p>'; return; }\n  box.innerHTML=S.ordenes.slice(0,12).map(o=>{\n    const st=OST[o.estado]||OST.nueva;\n    let extra='';\n    if(o.resumen) extra+='<p class=\"sub\">'+esc(o.resumen)+'</p>';\n    if(Array.isArray(o.reparto)&&o.reparto.length) extra+='<ul class=\"reparto\">'+o.reparto.map(r=>'<li><b>'+esc(nombreAg(r.agente))+'</b>: '+esc(r.tarea)+'</li>').join('')+'</ul>';\n    let acts='';\n    if(o.estado==='propuesta'&&S.canWrite) acts='<div class=\"row\"><button class=\"btn\" data-ap=\"'+esc(o.id)+'\" type=\"button\">Aprobar</button><button class=\"btn ghost\" data-rj=\"'+esc(o.id)+'\" type=\"button\">Rechazar</button></div>';\n    return '<div class=\"order\"><span class=\"chip\" style=\"--c:'+st.c+'\">'+st.t+'</span><p>'+esc(o.texto)+'</p>'+extra+acts+'<span class=\"meta\">'+esc(o.por||'')+' · '+ago(o.creado)+'</span></div>';\n  }).join('');\n}\n\nfunction deskHTML(a,lat){\n  const s=stateOf(a,lat), st=ST[s.k], tk=tareasDe(a.id).length;\n  const idleTxt=(s.k==='none')?'Todavía no reportó':(s.k==='idle'?'Descansando':'');\n  const txt=s.paso||idleTxt||(a.rol||'');\n  const mark={waiting_user:'!',error:'×',done:'✓'}[s.k]||'';\n  return '<button class=\"desk wk\" type=\"button\" data-id=\"'+esc(a.id)+'\" data-st=\"'+s.k+'\" style=\"--c:'+st.c+'\" aria-label=\"'+esc(a.nombre+', '+st.t)+'\">'+\n    '<div class=\"bub\"><span>'+esc(txt)+'</span></div>'+\n    '<div class=\"who\"><span class=\"zz\">z z</span><span class=\"badge\">'+mark+'</span>'+\n      '<div class=\"av2\">'+avatar(a.look)+'</div>'+\n      '<div class=\"mon\"><i></i><i></i><i></i></div>'+\n      '<div class=\"dk\"><div class=\"top\"></div><div class=\"leg\"></div></div></div>'+\n    '<div class=\"tag\"><b>'+esc(a.nombre)+'</b><small>'+st.t+(tk?' · '+tk+' tarea'+(tk>1?'s':''):'')+'</small></div></button>';\n}\n\nfunction renderFloors(lat){\n  if(!S.agentes.length){ $('floors').innerHTML=S.got.agentes?'<div class=\"block\"><p class=\"calm\">Todavía no hay agentes cargados en la oficina.</p></div>':''; return; }\n  const byP={};\n  for(const a of S.agentes){ (byP[a.piso]=byP[a.piso]||[]).push(a); }\n  const pisos=Object.keys(byP).map(Number).sort((x,y)=>y-x);\n  $('floors').innerHTML='<div class=\"building\">'+pisos.map(p=>{\n    const list=byP[p].sort((x,y)=>(x.orden||0)-(y.orden||0));\n    const w=list.filter(a=>stateOf(a,lat).k==='working').length;\n    return '<section class=\"floor\" aria-label=\"'+esc(PISOS[p]||('Piso '+p))+'\"><div class=\"plate\"><span>'+(p===0?'PB':'PISO')+'</span>'+(p===0?'':'<b>'+p+'</b>')+'</div><div class=\"room\"><div class=\"rhead\"><h2>'+esc(PISOS[p]||list[0].equipo||'')+'</h2><span class=\"fc\">'+esc(respDe(p))+' · '+w+' de '+list.length+' trabajando</span></div><div class=\"desks\">'+list.map(a=>deskHTML(a,lat)).join('')+'</div></div></section>';\n  }).join('')+'</div>';\n}\n\nfunction renderFeed(){\n  const ev=S.eventos.slice(0,12);\n  $('feed').innerHTML=ev.length?ev.map(e=>{\n    const st=ST[e.estado]||ST.none;\n    return '<div class=\"ev\"><span class=\"dot\" style=\"--c:'+st.c+'\"></span><span><b>'+esc(nombreAg(e.agente))+'</b> · '+esc(e.paso||st.t)+'</span><span class=\"t\">'+ago(e.at)+'</span></div>';\n  }).join(''):'<p class=\"calm\">Todavía no hay movimientos. Aparecen cuando los agentes empiecen a reportar.</p>';\n}\n\nfunction renderSheet(){\n  if(!S.sel) return;\n  const a=S.agentes.find(x=>x.id===S.sel); if(!a) return;\n  const lat=latest(), s=stateOf(a,lat), st=ST[s.k];\n  $('sh-title').textContent=a.nombre;\n  const hist=S.eventos.filter(e=>e.agente===a.id).slice(0,6);\n  const tk=tareasDe(a.id);\n  $('shbody').innerHTML=\n    '<p class=\"sub\">'+esc(a.rol||'')+'</p>'+\n    '<div class=\"row\"><span class=\"chip\" style=\"--c:'+st.c+'\">'+st.t+'</span><span class=\"meta\">'+(s.at?ago(s.at):'sin reportes todavía')+'</span></div>'+\n    (s.paso?'<p style=\"margin:0;overflow-wrap:anywhere\">'+esc(s.paso)+'</p>':'')+\n    (a.nohace?'<h4>Lo que no hace</h4><p class=\"meta\" style=\"margin:0\">'+esc(a.nohace)+'</p>':'')+\n    (a.horario?'<h4>Cuándo corre</h4><p class=\"meta\" style=\"margin:0\">'+esc(a.horario)+'</p>':'')+\n    '<h4>Tareas que le dio el gabinete</h4>'+(tk.length?'<ul>'+tk.map(t=>'<li>'+esc(t.texto)+'</li>').join('')+'</ul>':'<p class=\"calm\">Ninguna pendiente.</p>')+\n    '<h4>Últimos movimientos</h4>'+(hist.length?'<ul>'+hist.map(e=>'<li>'+esc(e.paso||(ST[e.estado]||ST.none).t)+' <span class=\"meta\">· '+ago(e.at)+'</span></li>').join('')+'</ul>':'<p class=\"calm\">Sin movimientos.</p>');\n  const isP=a.tipo==='persona';\n  $('pform').hidden=!(isP&&S.canWrite);\n  if(isP && $('pnom').dataset.for!==a.id && document.activeElement!==$('pnom')){ $('pnom').value=a.nombre||''; $('pnom').dataset.for=a.id; }\n}\n\nfunction renderAll(){\n  const lat=latest();\n  renderCounts(lat); renderAttn(lat); renderOrders(); renderFloors(lat); renderFeed(); renderSheet(); renderSide(lat); renderTeam(lat);\n  if(window.sync3D) window.sync3D(lat);\n  $('legend').innerHTML=['working','waiting_user','done','idle','error'].map(k=>'<span><i class=\"dot\" style=\"--c:'+ST[k].c+'\"></i>'+ST[k].t+'</span>').join('');\n}\nlet pend=false;\nfunction schedule(){ if(pend) return; pend=true; requestAnimationFrame(()=>{pend=false; renderAll();}); }\n\n\n/* ---- panel lateral y equipo ---- */\nconst PRIO={error:0,waiting_user:1,working:2,done:3,idle:4,none:5};\nfunction goFocus(k){ k=(k==='all')?null:k; if(window.OF) window.OF.setFocus(k); else { S.focusK=k; renderAll(); } }\nfunction renderSide(lat){\n  const byP={}; for(const a of S.agentes){ (byP[a.piso]=byP[a.piso]||[]).push(a); }\n  const ps=Object.keys(byP).map(Number).sort((x,y)=>y-x);\n  const cur=(S.focusK==null)?'all':String(S.focusK);\n  let h='<button type=\"button\" class=\"piso\" data-k=\"all\" aria-pressed=\"'+(cur==='all')+'\"><span class=\"no\">★</span><span class=\"nm\">Toda la oficina</span><span class=\"ct\"></span></button>';\n  h+=ps.map(p=>{ const l=byP[p], w=l.filter(a=>stateOf(a,lat).k==='working').length, nm=PISOS[p]||('Piso '+p);\n    return '<button type=\"button\" class=\"piso\" data-k=\"'+p+'\" aria-pressed=\"'+(cur===String(p))+'\"><span class=\"no\">'+(p===0?'PB':p)+'</span><span class=\"nm\">'+esc(nm)+'<small>'+l.length+(l.length===1?' integrante':' integrantes')+'</small></span><span class=\"ct\">'+(w?'<i></i>':'')+w+'/'+l.length+'</span></button>'; }).join('');\n  if(0) h+='<button type=\"button\" class=\"piso\" data-k=\"meet\" aria-pressed=\"'+(cur==='meet')+'\"><span class=\"no\">⚑</span><span class=\"nm\">Sala de reuniones<small>propuestas para aprobar</small></span><span class=\"ct\"></span></button>';\n  if(0) h+='<button type=\"button\" class=\"piso\" data-k=\"cafe\" aria-pressed=\"'+(cur==='cafe')+'\"><span class=\"no\">☕</span><span class=\"nm\">Café<small>los que descansan</small></span><span class=\"ct\"></span></button>';\n  $('pisos').innerHTML=h;\n  $('n-esp').textContent=document.querySelectorAll('#attn .attn-item').length;\n  const fin=S.agentes.filter(a=>stateOf(a,lat).k==='done');\n  $('n-fin').textContent=fin.length;\n  $('fin').innerHTML=fin.length?'<div class=\"mini\">'+fin.map(a=>'<div><span>'+esc(a.nombre)+'</span><small>'+esc(ago(stateOf(a,lat).at))+'</small></div>').join('')+'</div>':'<p class=\"calm\">Nada terminado todavía.</p>';\n  const rut=S.agentes.filter(a=>a.tipo!=='persona'&&a.horario);\n  $('n-rut').textContent=rut.length;\n  $('rut').innerHTML=rut.length?'<div class=\"mini\">'+rut.map(a=>'<div><span>'+esc(a.nombre)+'</span><small>'+esc(a.horario)+'</small></div>').join('')+'</div>':'';\n}\nfunction renderTeam(lat){\n  const k=S.focusK, box=$('team');\n  let list=[], title='Toda la oficina', num='★', sub='', resp='';\n  if(k==null){ list=S.agentes.slice(); }\n  else if(k==='cafe'){ list=S.agentes.filter(a=>['idle','none'].includes(stateOf(a,lat).k)); title='Café'; num='☕'; sub='Los que descansan'; }\n  else if(k==='meet'){\n    title='Sala de reuniones'; num='⚑'; sub='Propuestas del jefe';\n    const ps=S.ordenes.filter(o=>o.estado==='propuesta');\n    box.innerHTML='<div class=\"th\"><span class=\"no\">'+num+'</span><div><h2>'+title+'</h2><small>'+sub+'</small></div></div>'+(ps.length?ps.map(o=>'<div class=\"order\"><span class=\"chip\" style=\"--c:'+OST.propuesta.c+'\">propuesta</span><p>'+esc(o.texto)+'</p>'+(o.resumen?'<p class=\"sub\">'+esc(o.resumen)+'</p>':'')+(S.canWrite?'<div class=\"row\"><button class=\"btn\" data-ap=\"'+esc(o.id)+'\" type=\"button\">Aprobar</button><button class=\"btn ghost\" data-rj=\"'+esc(o.id)+'\" type=\"button\">Rechazar</button></div>':'')+'</div>').join(''):'<p class=\"calm\">Nada espera tu OK.</p>');\n    return;\n  }\n  else { const p=Number(k); list=S.agentes.filter(a=>a.piso===p); title=PISOS[p]||('Piso '+p); num=(p===0?'PB':p); const r=list.find(a=>a.tipo==='persona'); resp=r?'<div class=\"resp\"><small>'+esc(CARGO[p]||'Responsable')+'</small><b>'+esc(r.nombre)+'</b></div>':''; }\n  list.sort((a,b)=>(PRIO[stateOf(a,lat).k]-PRIO[stateOf(b,lat).k])||((a.orden||0)-(b.orden||0)));\n  const w=list.filter(a=>stateOf(a,lat).k==='working').length;\n  box.innerHTML='<div class=\"th\"><span class=\"no\">'+num+'</span><div><h2>'+esc(title)+'</h2><small>'+(sub||list.length+(list.length===1?' integrante':' integrantes'))+'</small></div><span class=\"okb\">'+w+' trabajando</span></div>'+resp+\n    '<div class=\"mrows\">'+(list.length?list.map(a=>{ const s=stateOf(a,lat), st=ST[s.k]||ST.idle; const tk=tareasDe(a.id).length;\n      const txt=s.paso||(a.tipo==='persona'?(a.rol||''):(s.k==='none'?'Todavía no reportó':(a.rol||'')));\n      return '<button class=\"mrow\" type=\"button\" data-id=\"'+esc(a.id)+'\" style=\"--c:'+st.c+'\"><span class=\"av\">'+cara(a)+'</span><span class=\"tx\"><b>'+esc(a.nombre)+'</b><small>'+esc(txt)+(tk?' · '+tk+(tk===1?' tarea':' tareas'):'')+'</small></span><span class=\"stc\"><i></i>'+esc(st.t)+'</span></button>'; }).join(''):'<p class=\"calm\">Nadie en esta zona.</p>')+'</div>';\n}\n\n\nconst SKIN_=['#f1c9a5','#e0ac82','#c68863','#9a6a47','#f6d7bd'], HAIR_=['#2b2118','#4a3224','#1c1c22','#8a5a2b','#b88b4a','#6b2d2d'], MUJ_={barbara:1,jime:1,georgina:1,debora:1};\nfunction hsh_(s){ let h=7; for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))|0; return Math.abs(h); }\nfunction cara(a){\n  const id=a.id||'x', col=(a.look&&a.look.color)||'#8a919e', h=hsh_(id), skin=SKIN_[h%5], hair=HAIR_[(h>>3)%6], mujer=!!MUJ_[id], ia=a.tipo!=='persona';\n  const pelo=mujer?'<path d=\"M14 36c-1-16 7-24 18-24s19 8 18 24c0 4-1 8-3 12 0-10-3-18-15-18S17 38 17 48c-2-4-3-8-3-12z\" fill=\"'+hair+'\"/>':'<path d=\"M16 32c0-13 7-20 16-20s16 7 16 20c-5-6-10-8-16-8s-11 2-16 8z\" fill=\"'+hair+'\"/>';\n  const aur=ia?'<path d=\"M14 34a18 18 0 0 1 36 0\" fill=\"none\" stroke=\"#161a26\" stroke-width=\"3.5\"/><rect x=\"10\" y=\"32\" width=\"7\" height=\"10\" rx=\"3\" fill=\"#161a26\"/><rect x=\"47\" y=\"32\" width=\"7\" height=\"10\" rx=\"3\" fill=\"#161a26\"/>':'';\n  return '<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><path d=\"M6 64c0-12 10-18 26-18s26 6 26 18z\" fill=\"'+col+'\"/><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"'+skin+'\"/>'+pelo+'<circle cx=\"27\" cy=\"33\" r=\"1.8\" fill=\"#151515\"/><circle cx=\"37\" cy=\"33\" r=\"1.8\" fill=\"#151515\"/><path d=\"M28 40q4 3 8 0\" fill=\"none\" stroke=\"#8a3b3b\" stroke-width=\"1.6\" stroke-linecap=\"round\"/>'+aur+'</svg>';\n}\n/* acciones */\ndocument.addEventListener('click',async ev=>{\n  const t=ev.target.closest('button'); if(!t) return;\n  if(t.classList.contains('piso')){ goFocus(t.dataset.k); return; }\n  if(t.classList.contains('desk')||t.classList.contains('mrow')){ S.sel=t.dataset.id; $('sheet').hidden=false; renderSheet(); return; }\n  if(t.id==='shclose'){ S.sel=null; $('sheet').hidden=true; return; }\n  if(t.dataset.ap||t.dataset.rj){\n    const id=t.dataset.ap||t.dataset.rj;\n    try{ await S.db.doc('ordenes/'+id).update({estado:t.dataset.ap?'aprobada':'rechazada',decidida:new Date().toISOString()}); }\n    catch(e){ $('orderr').hidden=false; $('orderr').textContent='No se pudo guardar. Probá de nuevo.'; }\n  }\n});\n$('sheet').addEventListener('click',e=>{ if(e.target===$('sheet')){ S.sel=null; $('sheet').hidden=true; } });\ndocument.addEventListener('keydown',e=>{ if(e.key==='Escape'&&!$('sheet').hidden){ S.sel=null; $('sheet').hidden=true; } });\n\n$('ordsend').addEventListener('click',async()=>{\n  const txt=$('ordtxt').value.trim(), er=$('orderr'); er.hidden=true;\n  if(!txt) return;\n  if(!S.db||!S.canWrite){ er.hidden=false; er.textContent='Tu usuario no puede escribir en la oficina.'; return; }\n  $('ordsend').disabled=true;\n  try{\n    await S.db.collection('ordenes').add({texto:txt.slice(0,1500),estado:'nueva',creado:new Date().toISOString(),por:(S.user&&S.user.isOwner&&S.user.isOwner())?'Julio':'equipo'});\n    $('ordtxt').value='';\n  }catch(e){ er.hidden=false; er.textContent='No se pudo enviar. Probá de nuevo.'; }\n  $('ordsend').disabled=false;\n});\n$('psave').addEventListener('click',async()=>{\n  const er=$('perr'); er.hidden=true;\n  if(!S.db||!S.sel) return;\n  $('psave').disabled=true;\n  try{\n    await S.db.collection('eventos').add({agente:S.sel,estado:$('pst').value,paso:$('ppaso').value.trim().slice(0,60),at:new Date().toISOString(),por:'panel'});\n    $('ppaso').value='';\n  }catch(e){ er.hidden=false; er.textContent='No se pudo guardar. Probá de nuevo.'; }\n  $('psave').disabled=false;\n});\n\n/* conexión */\nfunction sub(name,query,key){\n  let first=true;\n  return query.onSnapshot(snap=>{\n    S[key]=snap.docs.map(d=>Object.assign({id:d.id},d.data()));\n    S.got[key]=true;\n    if(!snap.metadata.fromCache) { $('sync').textContent='En vivo · actualizado '+new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'}); $('sync').dataset.bad=''; clearTimeout(S.timer); }\n    schedule();\n  },err=>{\n    $('sync').textContent='No se pudo leer «'+name+'» ('+(err&&err.code||'error')+').'; $('sync').dataset.bad='1';\n  });\n}\nasync function start(){\n  renderAll();\n  S.timer=setTimeout(()=>{ $('sync').textContent='Todavía no hay respuesta de la base; los datos pueden estar desactualizados.'; $('sync').dataset.bad='1'; },10000);\n  try{\n    S.user=await window.claude.use('user');\n    S.db=await window.claude.use('db');\n  }catch(e){}\n  if(!S.db){ clearTimeout(S.timer); $('sync').textContent='Sin conexión con la base.'; $('sync').dataset.bad='1'; $('ordsend').disabled=true; return; }\n  try{ const cw=S.user&&S.user.can?S.user.can('data.write'):null; S.canWrite=cw!==false; }catch(e){ S.canWrite=true; }\n  sub('agentes',S.db.collection('agentes'),'agentes');\n  sub('eventos',S.db.collection('eventos').orderBy('at','desc').limit(400),'eventos');\n  sub('órdenes',S.db.collection('ordenes').orderBy('creado','desc').limit(30),'ordenes');\n  sub('tareas',S.db.collection('tareas').limit(300),'tareas');\n  setInterval(schedule,60000);\n}\nstart();\n</script>\n<script>\n/* Torre de oficinas en 3D: un piso por área, un robot por agente o persona. */\n(function(){\n'use strict';\nconst stage=document.getElementById('stage'), cv=document.getElementById('cv');\nlet ok=false;\ntry{ if(window.THREE){ const c=document.createElement('canvas'); ok=!!(c.getContext('webgl')||c.getContext('experimental-webgl')); } }catch(e){}\nif(!ok){ stage.hidden=true; return; }\nconst T=window.THREE;\nlet renderer;\ntry{ renderer=new T.WebGLRenderer({antialias:true,alpha:true}); }catch(e){ stage.hidden=true; return; }\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));\nrenderer.shadowMap.enabled=true; renderer.shadowMap.type=T.PCFSoftShadowMap;\ncv.appendChild(renderer.domElement);\nrenderer.domElement.setAttribute('aria-label','Torre de la oficina en 3D');\nconst reduce=matchMedia('(prefers-reduced-motion: reduce)').matches, M=reduce?0.2:1;\nconst isDark=()=>{ const r=document.documentElement.dataset.theme; if(r==='dark') return true; if(r==='light') return false; return matchMedia('(prefers-color-scheme: dark)').matches; };\nconst SC={working:'#3B82F6',done:'#16A34A',waiting_user:'#F5A524',error:'#E5484D',idle:'#8A919E',none:'#8A919E'};\n\nconst scene=new T.Scene(), cam=new T.PerspectiveCamera(30,1,.1,400);\nconst hemi=new T.HemisphereLight(0xffffff,0xb8c0d0,.85); scene.add(hemi);\nconst sun=new T.DirectionalLight(0xffffff,.65); sun.position.set(14,26,18); sun.castShadow=true;\nsun.shadow.mapSize.set(2048,2048); const sc=sun.shadow.camera; sc.left=-26; sc.right=26; sc.top=34; sc.bottom=-6; sc.near=1; sc.far=90; sun.shadow.bias=-.0008;\nscene.add(sun); scene.add(sun.target);\nconst fill=new T.DirectionalLight(0xdfe8ff,.25); fill.position.set(-14,10,12); scene.add(fill);\n\nconst W=12.6, H=3.6, ROWH=2.7;\nlet lift=null, root=null, floors=[], ents=new Map(), hitList=[], focusK=null, yawOff=0, towerH=10, rowsMax=2, D=8;\nconst cur={tx:0,ty:5,dist:40}, tgt={tx:0,ty:5,dist:40};\nconst PITCH=.4, YAW0=.62;\n\nfunction std(c,o){ return new T.MeshStandardMaterial(Object.assign({color:c,roughness:.85,metalness:0},o||{})); }\nfunction box(w,h,d,mat,x,y,z,sh,parent){ const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat); m.position.set(x,y,z); if(sh!==false){ m.castShadow=true; m.receiveShadow=true; } (parent||root).add(m); return m; }\nfunction mix(hex,k){ const c=new T.Color(hex); return c.lerp(new T.Color(0xffffff),k); }\nfunction rr(x,a,b,w,h,r){ x.beginPath(); x.moveTo(a+r,b); x.arcTo(a+w,b,a+w,b+h,r); x.arcTo(a+w,b+h,a,b+h,r); x.arcTo(a,b+h,a,b,r); x.arcTo(a,b,a+w,b,r); x.closePath(); }\nfunction sprite(w,h,sw,sh){ const c=document.createElement('canvas'); c.width=w; c.height=h; const tex=new T.CanvasTexture(c); tex.anisotropy=4; const m=new T.SpriteMaterial({map:tex,transparent:true,depthWrite:false}); const sp=new T.Sprite(m); sp.scale.set(sw,sh,1); sp.userData={x:c.getContext('2d'),tex,w,h}; sp.renderOrder=10; return sp; }\nfunction clip(x,t,maxW){ if(x.measureText(t).width<=maxW) return t; while(t.length>2&&x.measureText(t+'…').width>maxW) t=t.slice(0,-1); return t+'…'; }\n\nfunction makeBubble(){\n  const sp=sprite(520,150,3.3,.95); let last='';\n  sp.userData.set=(name,role,paso,col)=>{\n    const key=name+'|'+role+'|'+paso+'|'+col; if(key===last) return; last=key;\n    const x=sp.userData.x; x.clearRect(0,0,520,150);\n    rr(x,4,4,512,118,22); x.fillStyle='rgba(17,20,28,.94)'; x.fill();\n    x.beginPath(); x.moveTo(240,120); x.lineTo(260,142); x.lineTo(280,120); x.fill();\n    x.fillStyle=col; x.beginPath(); x.arc(34,36,9,0,7); x.fill();\n    x.textBaseline='middle'; x.textAlign='left';\n    x.fillStyle='#fff'; x.font='700 25px Helvetica,Arial,sans-serif'; x.fillText(clip(x,name.toUpperCase(),420),54,36);\n    x.fillStyle='#aab2c3'; x.font='500 21px Helvetica,Arial,sans-serif'; x.fillText(clip(x,role,470),30,66);\n    x.fillStyle='#fff'; x.font='600 24px Helvetica,Arial,sans-serif'; x.fillText(clip(x,paso||'',470),30,98);\n    sp.userData.tex.needsUpdate=true;\n  };\n  return sp;\n}\nfunction makeLabel(){\n  const sp=sprite(560,110,3.5,.69); let last='';\n  sp.userData.set=(no,text,sub,col)=>{\n    const key=no+'|'+text+'|'+sub+'|'+col; if(key===last) return; last=key;\n    const x=sp.userData.x; x.clearRect(0,0,560,110);\n    rr(x,3,3,554,104,26); x.fillStyle='rgba(17,20,28,.94)'; x.fill();\n    rr(x,14,14,82,82,18); x.fillStyle=col; x.fill();\n    x.fillStyle='#fff'; x.textAlign='center'; x.textBaseline='middle'; x.font='800 44px Helvetica,Arial,sans-serif'; x.fillText(no,55,57);\n    x.textAlign='left'; let fs=34; x.font='700 '+fs+'px Helvetica,Arial,sans-serif'; while(x.measureText(text).width>420&&fs>20){ fs-=2; x.font='700 '+fs+'px Helvetica,Arial,sans-serif'; }\n    x.fillText(clip(x,text,430),114,42);\n    x.fillStyle='#aab2c3'; x.font='600 26px Helvetica,Arial,sans-serif'; x.fillText(sub,114,80);\n    sp.userData.tex.needsUpdate=true;\n  };\n  return sp;\n}\nfunction makeBadge(){ return sprite(128,128,.72,.72); }\nfunction drawBadge(sp,col,glyph){\n  const x=sp.userData.x; x.clearRect(0,0,128,128);\n  x.fillStyle=col; x.beginPath(); x.arc(64,64,52,0,7); x.fill(); x.lineWidth=7; x.strokeStyle='#fff'; x.stroke();\n  x.fillStyle='#fff'; x.font='800 66px Helvetica,Arial,sans-serif'; x.textAlign='center'; x.textBaseline='middle'; x.fillText(glyph,64,70);\n  sp.userData.tex.needsUpdate=true;\n}\n\n/* ---- personas (agentes y equipo) ---- */\nconst SKIN=[0xf1c9a5,0xe0ac82,0xc68863,0x9a6a47,0xf6d7bd], HAIR=[0x2b2118,0x4a3224,0x1c1c22,0x8a5a2b,0xb88b4a,0x6b2d2d];\nconst MUJ={barbara:1,jime:1,georgina:1,debora:1};\nfunction hsh(str){ let h=7; for(let i=0;i<str.length;i++) h=(h*31+str.charCodeAt(i))|0; return Math.abs(h); }\nfunction makeRobot(look,id,tipo){\n  const hs=hsh(id||'x'), skin=std(SKIN[hs%SKIN.length],{roughness:.7}), hairM=std(HAIR[(hs>>3)%HAIR.length],{roughness:.8});\n  const col=new T.Color((look&&look.color)||'#8a919e'), cloth=std(col,{roughness:.65}), pants=std(0x2c3446,{roughness:.8}), dark=std(0x161a26,{roughness:.5});\n  const g=new T.Group(), inner=new T.Group(); g.add(inner); g.userData.inner=inner;\n  const add=(geo,mat,x,y,z,par)=>{ const m=new T.Mesh(geo,mat); m.position.set(x,y,z); m.castShadow=true; (par||inner).add(m); return m; };\n  // piernas sentadas\n  for(const sx of[-1,1]){ add(new T.BoxGeometry(.22,.2,.62),pants,sx*.14,.14,.3); add(new T.BoxGeometry(.2,.5,.2),pants,sx*.14,-.12,.56); add(new T.BoxGeometry(.22,.1,.3),dark,sx*.14,-.34,.64); }\n  // torso\n  add(new T.CylinderGeometry(.3,.34,.62,18),cloth,0,.38,0);\n  add(new T.CylinderGeometry(.11,.12,.14,12),skin,0,.74,0);\n  const hd=new T.Group(); hd.position.set(0,1.02,0); inner.add(hd); g.userData.head=hd;\n  const mujer=!!MUJ[id], ped=hs%4;\n  const hm=new T.Mesh(new T.SphereGeometry(.27,22,18),skin); hm.castShadow=true; hd.add(hm);\n  // pelo\n  const cap=new T.Mesh(new T.SphereGeometry(.295,22,16,0,Math.PI*2,0,Math.PI*(mujer?.62:.5)),hairM); cap.rotation.x=-.28; cap.position.set(0,.02,-.02); cap.castShadow=true; hd.add(cap);\n  if(mujer){ const back=new T.Mesh(new T.BoxGeometry(.5,.62,.2),hairM); back.position.set(0,-.14,-.2); back.castShadow=true; hd.add(back); }\n  else if(ped===1){ const bun=new T.Mesh(new T.SphereGeometry(.12,12,10),hairM); bun.position.set(0,.3,-.12); hd.add(bun); }\n  // cara\n  const eyeM=new T.MeshBasicMaterial({color:0x111111}), eyes=[];\n  for(const sx of[-1,1]){ const e=new T.Mesh(new T.SphereGeometry(.036,8,8),new T.MeshBasicMaterial({color:0x151515})); e.position.set(sx*.095,.03,.255); hd.add(e); eyes.push(e); }\n  const mouth=new T.Mesh(new T.BoxGeometry(.1,.018,.02),new T.MeshBasicMaterial({color:0x8a3b3b})); mouth.position.set(0,-.09,.262); hd.add(mouth);\n  // brazos\n  const arms=[]; for(const sx of[-1,1]){ const a=new T.Group(); a.position.set(sx*.4,.58,.02); const m=new T.Mesh(new T.CylinderGeometry(.075,.07,.46,10),cloth); m.position.y=-.2; m.castShadow=true; a.add(m); const hand=new T.Mesh(new T.SphereGeometry(.075,10,8),skin); hand.position.y=-.45; a.add(hand); inner.add(a); arms.push(a); }\n  // marca: auriculares con micrófono (agentes IA) o credencial (equipo); el LED cambia con el estado\n  let bulb;\n  if(tipo==='persona'){ add(new T.BoxGeometry(.16,.2,.02),std(0xffffff),.12,.52,.31); bulb=add(new T.SphereGeometry(.045,10,8),new T.MeshBasicMaterial({color:0xffffff}),.12,.55,.33); }\n  else { const band=new T.Mesh(new T.TorusGeometry(.29,.026,8,24,Math.PI),dark); band.rotation.z=0; band.position.set(0,.02,0); hd.add(band); for(const sx of[-1,1]){ const cup=new T.Mesh(new T.CylinderGeometry(.075,.075,.06,12),dark); cup.rotation.z=Math.PI/2; cup.position.set(sx*.29,.02,0); hd.add(cup); } const boom=new T.Mesh(new T.BoxGeometry(.02,.02,.2),dark); boom.position.set(.29,-.05,.1); boom.rotation.y=-.5; hd.add(boom); bulb=new T.Mesh(new T.SphereGeometry(.035,10,8),new T.MeshBasicMaterial({color:0xffffff})); bulb.position.set(.2,-.08,.22); hd.add(bulb); }\n  g.userData.eyes=eyes; g.userData.eyeM=eyeM; g.userData.bulb=bulb; g.userData.arms=arms;\n  return g;\n}\n\nfunction disposeRoot(){\n  if(!root) return;\n  root.traverse(o=>{ if(o.geometry) o.geometry.dispose(); if(o.material){ if(o.material.map) o.material.map.dispose(); o.material.dispose(); } });\n  scene.remove(root); root=null; floors=[]; ents=new Map(); hitList=[];\n}\nfunction groups(){\n  const by={}; for(const a of S.agentes){ (by[a.piso]=by[a.piso]||[]).push(a); }\n  return Object.keys(by).map(Number).sort((x,y)=>x-y).map(p=>({piso:p,list:by[p].sort((x,y)=>(x.orden||0)-(y.orden||0))}));\n}\nfunction build(){\n  disposeRoot(); root=new T.Group(); scene.add(root);\n  const dark=isDark(), gs=groups();\n  hemi.intensity=dark?.5:.85; sun.intensity=dark?.4:.65;\n  const wallC=dark?0x39415a:0xeceef3, slabC=dark?0x2b3146:0xf6f4ef, glassC=dark?0x2f4a78:0xbfe0ff;\n  rowsMax=Math.max(1,...gs.map(g=>Math.ceil(g.list.length/5))); D=2.4+rowsMax*ROWH;\n  towerH=gs.length*H;\n  // base y suelo\n  box(W+8,.5,D+6,std(dark?0x1d2a22:0xcfe3c4),0,-.6,0.6,false);\n  // ascensor\n  lift=box(1.9,towerH+.6,1.9,std(glassC,{transparent:true,opacity:.35,roughness:.1}),W/2+1.4,towerH/2-.1,-D/2+1.2,false);\n  for(const [x,z] of [[-1,-1],[1,-1],[-1,1],[1,1]]) lift.add(new T.Mesh(new T.BoxGeometry(.1,towerH+.7,.1),std(dark?0x8a92a8:0xc6ccd8))); if(0) box(.1,towerH+.7,.1,std(dark?0x8a92a8:0xc6ccd8),W/2+1.4+x*.95,towerH/2-.1,-D/2+1.2+z*.95,false);\n  gs.forEach((G,i)=>{\n    const y=i*H, grp=new T.Group(); grp.position.y=y; root.add(grp); floors.push({piso:G.piso,grp,lab:null});\n    const tc=mix((G.list.find(a=>a.look&&a.look.color)||{look:{color:'#8a919e'}}).look.color,.78);\n    const P=(w,h,d,mat,x,yy,z,sh)=>box(w,h,d,mat,x,yy,z,sh,grp);\n    P(W,.4,D,std(slabC),0,-.2,0);\n    P(W-1.4,.03,D-1,std(tc,{roughness:.95}),-.2,.02,.1,false);\n    P(W,H-.4,.25,std(wallC),0,(H-.4)/2,-D/2);\n    P(.25,H-.4,D,std(wallC),-W/2,(H-.4)/2,0);\n    for(const wx of [-3.4,.4,4.2]){ P(2.8,1.5,.06,std(glassC,{transparent:true,opacity:.7,roughness:.1}),wx,2.05,-D/2+.16,false); }\n    // pizarra con notas\n    P(2.2,1.3,.06,std(0xffffff),W/2-1.6,1.9,-D/2+.18,false);\n    [[0xffd966,-.6,.3],[0xff9db1,0,.35],[0x9ad7ff,.55,.25],[0xb5f0a8,-.35,-.3],[0xffb870,.35,-.28]].forEach(n=>P(.3,.28,.02,new T.MeshBasicMaterial({color:n[0]}),W/2-1.6+n[1],1.9+n[2],-D/2+.23,false));\n    // planta\n    P(.34,.4,.34,std(0xf3f3f3),W/2-.7,.2,D/2-.9);\n    const pl=new T.Mesh(new T.SphereGeometry(.5,14,10),std(dark?0x2b7a52:0x4cae6e)); pl.position.set(W/2-.7,.95,D/2-.9); pl.castShadow=true; grp.add(pl);\n    const pl2=new T.Mesh(new T.SphereGeometry(.34,12,8),std(dark?0x2b7a52:0x5ec47f)); pl2.position.set(W/2-.5,1.4,D/2-.95); pl2.castShadow=true; grp.add(pl2);\n    // sillón de descanso\n    // escritorios + robots\n    const n=G.list.length, cols=Math.min(5,n), sx=2.3;\n    G.list.forEach((a,k)=>{\n      const r=Math.floor(k/5), c=k%5, inRow=Math.min(5,n-r*5), x=(c-(inRow-1)/2)*sx-.2, z=-D/2+1.5+r*ROWH;\n      const deskZ=z+.9;\n      P(1.8,.08,.9,std(0xf8f6f1,{roughness:.6}),x,.78,deskZ);\n      P(.08,.76,.8,std(0xd9d5cc),x-.8,.38,deskZ,false); P(.08,.76,.8,std(0xd9d5cc),x+.8,.38,deskZ,false);\n      P(.62,.04,.42,std(0x2a2f3c),x,.84,deskZ-.05,false);\n      const lid=P(.62,.42,.04,std(0x2a2f3c),x,1.04,deskZ-.26,false); lid.rotation.x=-.18;\n      P(.7,.08,.64,std(0x474f63),x,.5,z-.02,false); P(.1,.5,.1,std(0x474f63),x,.24,z-.02,false);\n      const rb=makeRobot(a.look,a.id,a.tipo); rb.position.set(x,.62,z-.02); grp.add(rb);\n      const hit=new T.Mesh(new T.BoxGeometry(1.2,1.9,1.1),new T.MeshBasicMaterial({visible:false})); hit.position.set(x,1.1,z); hit.userData.agent=a.id; grp.add(hit); hitList.push(hit);\n      const bub=makeBubble(); bub.scale.set(3.7,1.07,1); bub.position.set(x,2.7+(c%2)*.85,z); bub.visible=false; grp.add(bub);\n      const badge=makeBadge(); badge.position.set(x+.62,2.0,z+.2); badge.visible=false; grp.add(badge);\n      const ring=new T.Mesh(new T.RingGeometry(.62,.7,32),new T.MeshBasicMaterial({color:0xf5a524,transparent:true,opacity:.7,side:T.DoubleSide})); ring.rotation.x=-Math.PI/2; ring.position.set(x,.06,z); ring.visible=false; grp.add(ring);\n      const nm=sprite(300,64,1.9,.4); nm.position.set(x,.05,deskZ+.62); nm.userData.set=(t)=>{ const q=nm.userData.x; q.clearRect(0,0,300,64); rr(q,2,6,296,52,16); q.fillStyle='rgba(255,255,255,.92)'; q.fill(); q.fillStyle='#161a26'; q.font='700 26px Helvetica,Arial,sans-serif'; q.textAlign='center'; q.textBaseline='middle'; q.fillText(clip(q,t,270),150,33); nm.userData.tex.needsUpdate=true; }; nm.userData.set(a.nombre); nm.position.y=.35; grp.add(nm);\n      ents.set(a.id,{id:a.id,a,rb,bub,badge,ring,nm,state:'',paso:'',x,z,ph:(k*1.7+i*.9)%6.28,piso:G.piso,floor:i});\n    });\n    const lab=makeLabel(); lab.material.depthTest=false; lab.scale.set(4.4,.86,1); lab.position.set(-W/2-.9,3.0,D/2-.4); grp.add(lab); floors[i].lab=lab;\n    floors[i].list=G.list;\n  });\n  setFocus(focusK,true);\n}\nfunction fit(w){ const t=Math.tan(T.MathUtils.degToRad(cam.fov/2)); return Math.max((w*.58)/(t*cam.aspect),(H*1.5)/(t))+3; }\nfunction setFocus(k,snap){\n  if(k==='meet'||k==='cafe') k=null;\n  if(k!=null && !floors.find(f=>String(f.piso)===String(k))) k=null;\n  focusK=k;\n  if(k==null){ tgt.tx=1.2; tgt.ty=towerH/2; tgt.dist=Math.max(fit(W+8)*.9,towerH*2.15)*1.22; }\n  else { const f=floors.find(f=>String(f.piso)===String(k)); const i=floors.indexOf(f); tgt.tx=-1.1; tgt.ty=i*H+1.3; tgt.dist=fit(W+2); }\n  floors.forEach((f,i)=>{ const fi=k==null?-1:floors.findIndex(q=>String(q.piso)===String(k)); f.grp.visible=(fi<0)||i===fi; }); if(lift) lift.visible=(k==null);\n  if(snap){ cur.tx=tgt.tx; cur.ty=tgt.ty; cur.dist=tgt.dist; }\n  S.focusK=focusK; if(window.onFocus) window.onFocus();\n}\nwindow.OF={setFocus:function(k){ yawOff=0; setFocus(k); }};\n\nfunction applyState(lat){\n  for(const e of ents.values()){\n    const a=S.agentes.find(x=>x.id===e.id)||e.a, s=stateOf(a,lat), k=s.k;\n    e.state=k; e.paso=s.paso||'';\n    const col=SC[k]||SC.idle;\n    const showB=(k==='working'||k==='waiting_user'||k==='error')&&(focusK==null?true:String(e.piso)===String(focusK));\n    e.bub.visible=showB; if(showB) e.bub.userData.set(a.nombre,(a.rol||'').split(',')[0],s.paso||ST[k].t,col);\n    e.badge.visible=(k==='waiting_user'||k==='error'||k==='done');\n    if(e.badge.visible) drawBadge(e.badge,col,k==='waiting_user'?'!':k==='error'?'×':'✓');\n    e.ring.visible=(k==='waiting_user'); if(k==='waiting_user') e.ring.material.color.set(col);\n    const m=e.rb.userData.eyeM, b=e.rb.userData.bulb.material;\n    b.color.set(col);\n  }\n  floors.forEach(f=>{ if(!f.lab) return; const w=(f.list||[]).filter(a=>stateOf(a,lat).k==='working').length; f.lab.userData.set(f.piso===0?'PB':String(f.piso),PISOS[f.piso]||('Piso '+f.piso),w+' de '+(f.list||[]).length+' trabajando',w?SC.working:'#6b7385'); });\n  applyBubblesVis();\n}\nfunction applyBubblesVis(){ for(const e of ents.values()){ const on=(e.state==='working'||e.state==='waiting_user'||e.state==='error')&&(focusK==null||String(e.piso)===String(focusK)); e.bub.visible=on; } }\nlet lastSig='';\nwindow.sync3D=function(lat){\n  if(!S.agentes.length){ stage.hidden=true; return; }\n  stage.hidden=false;\n  const sig=JSON.stringify(S.agentes.map(a=>[a.id,a.piso,a.orden,a.nombre,a.look]))+isDark();\n  if(sig!==lastSig){ lastSig=sig; build(); if(!S.focusInit){ S.focusInit=1; const f=floors.find(f=>f.piso===5)?'5':null; setFocus(f,true); } }\n  applyState(lat);\n};\n\n/* ---- interacción ---- */\nconst ray=new T.Raycaster(), v2=new T.Vector2(); let drag=null; const el=renderer.domElement;\nel.addEventListener('pointerdown',ev=>{ drag={x:ev.clientX,yo:yawOff,moved:false}; try{el.setPointerCapture(ev.pointerId);}catch(e){} });\nel.addEventListener('pointermove',ev=>{ if(!drag) return; const dx=ev.clientX-drag.x; if(Math.abs(dx)>6) drag.moved=true; if(drag.moved) yawOff=Math.max(-1.1,Math.min(1.1,drag.yo-dx*.005)); });\nel.addEventListener('pointerup',ev=>{\n  const d=drag; drag=null; if(!d||d.moved||!root) return;\n  const r=el.getBoundingClientRect(); v2.set(((ev.clientX-r.left)/r.width)*2-1,-((ev.clientY-r.top)/r.height)*2+1);\n  ray.setFromCamera(v2,cam); const hits=ray.intersectObjects(hitList.filter(h=>h.parent.visible),false); if(!hits.length) return;\n  const id=hits[0].object.userData.agent, e=ents.get(id); if(!e) return;\n  if(focusK==null){ yawOff=0; setFocus(String(e.piso)); } else { S.sel=id; $('sheet').hidden=false; renderSheet(); }\n});\nel.addEventListener('pointercancel',()=>{ drag=null; });\nel.addEventListener('dblclick',()=>{ yawOff=0; setFocus(null); });\n\nfunction resize(){ const w=cv.clientWidth, h=cv.clientHeight; if(!w||!h) return; renderer.setSize(w,h,false); el.style.width='100%'; el.style.height='100%'; cam.aspect=w/h; cam.updateProjectionMatrix(); if(root) setFocus(focusK,true); }\nnew ResizeObserver(resize).observe(cv);\nlet vis=true; new IntersectionObserver(es=>{ vis=es[0].isIntersecting; }).observe(cv);\nlet tPrev=performance.now(); const t0=tPrev;\nfunction loop(now){\n  requestAnimationFrame(loop);\n  if(!vis||document.hidden||!root){ tPrev=now; return; }\n  const t=(now-t0)/1000, dt=Math.min(.05,(now-tPrev)/1000); tPrev=now;\n  const k=1-Math.pow(.002,dt);\n  cur.tx+=(tgt.tx-cur.tx)*k; cur.ty+=(tgt.ty-cur.ty)*k; cur.dist+=(tgt.dist-cur.dist)*k;\n  const yaw=YAW0+yawOff+(drag?0:Math.sin(t*.2)*.05*M);\n  cam.position.set(cur.tx+Math.sin(yaw)*Math.cos(PITCH)*cur.dist, cur.ty+Math.sin(PITCH)*cur.dist, Math.cos(yaw)*Math.cos(PITCH)*cur.dist);\n  cam.lookAt(cur.tx,cur.ty,0);\n  for(const e of ents.values()){\n    const rb=e.rb, u=rb.userData, st=e.state, ph=e.ph; let by=0, rz=0, rx=0, ex=1, ey=1;\n    if(st==='working'){ u.arms[0].rotation.x=-1.25+Math.sin(t*14+ph)*.18*Math.max(M,.4); u.arms[1].rotation.x=-1.25+Math.sin(t*14+ph+2)*.18*Math.max(M,.4); u.head.rotation.x=.1+Math.sin(t*3+ph)*.03*M; by=Math.abs(Math.sin(t*7+ph))*.02*M; }\n    else if(st==='waiting_user'){ by=Math.abs(Math.sin(t*3+ph))*.28*M; u.arms[0].rotation.x=-2.9+Math.sin(t*9)*.35*M; u.arms[1].rotation.x=-1.0; u.head.rotation.x=0; rz=Math.sin(t*6)*.05*M; }\n    else if(st==='error'){ rz=Math.sin(t*38)*.045*M; u.arms[0].rotation.x=-.5; u.arms[1].rotation.x=-.5; u.head.rotation.x=0; }\n    else if(st==='done'){ by=Math.abs(Math.sin(t*2+ph))*.12*M; u.arms[0].rotation.x=-.3; u.arms[1].rotation.x=-.3; u.head.rotation.x=0; }\n    else { u.arms[0].rotation.x=-.25; u.arms[1].rotation.x=-.25; u.head.rotation.x=.28; ey=.12; by=Math.sin(t*1.4+ph)*.012*M; }\n    u.eyes.forEach(q=>{ q.scale.set(ex,ey,1); });\n    rb.userData.inner.position.y=by; rb.userData.inner.rotation.z=rz; rb.userData.inner.rotation.x=rx;\n    if(e.ring.visible){ const s=1+((t*.9+ph)%1)*.5; e.ring.scale.set(s,s,s); e.ring.material.opacity=.7*(1-((t*.9+ph)%1)); }\n    if(e.badge.visible) e.badge.position.y=2.05+Math.sin(t*4+ph)*.06*M;\n  }\n  renderer.render(scene,cam);\n}\nrequestAnimationFrame(loop);\nmatchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{ lastSig=''; schedule(); });\nnew MutationObserver(()=>{ lastSig=''; schedule(); }).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});\n})();\n</script>\n\n<script>\n/* Dictado por voz (el navegador transcribe; no se guarda el audio) y cambio de nombre de las personas del equipo */\n(function(){\n  var SR=window.SpeechRecognition||window.webkitSpeechRecognition, mic=document.getElementById('ordmic'), txt=document.getElementById('ordtxt');\n  if(SR&&mic&&txt){\n    mic.hidden=false; var rec=null, base='';\n    mic.addEventListener('click',function(){\n      if(rec){ rec.stop(); return; }\n      rec=new SR(); rec.lang='es-AR'; rec.interimResults=true; rec.continuous=true; base=txt.value?txt.value.replace(/\\s+$/,'')+' ':'';\n      rec.onresult=function(e){ var t=''; for(var i=0;i<e.results.length;i++) t+=e.results[i][0].transcript; txt.value=(base+t).slice(0,1500); };\n      rec.onend=function(){ rec=null; mic.setAttribute('aria-pressed','false'); mic.textContent='Dictar con el micrófono'; };\n      rec.onerror=function(){ };\n      mic.setAttribute('aria-pressed','true'); mic.textContent='Escuchando… tocá para terminar'; rec.start();\n    });\n  }\n  var nb=document.getElementById('pnsave');\n  if(nb) nb.addEventListener('click',function(){\n    var v=document.getElementById('pnom').value.trim(), er=document.getElementById('perr'); er.hidden=true;\n    if(!v||!S.sel) return; nb.disabled=true;\n    S.db.doc('agentes/'+S.sel).update({nombre:v}).then(function(){ var a=S.agentes.find(function(x){ return x.id===S.sel; }); if(a) a.nombre=v; document.getElementById('sh-title').textContent=v; if(window.renderAll) window.renderAll(); }).catch(function(){ er.hidden=false; er.textContent='No se pudo cambiar el nombre.'; }).then(function(){ nb.disabled=false; });\n  });\n})();\n\n/* Llamada de voz gratis: el navegador escucha y habla; el jefe responde con la propuesta */\n(function(){\n  var SR=window.SpeechRecognition||window.webkitSpeechRecognition, btn=document.getElementById('ordcall'), ss=window.speechSynthesis;\n  if(!SR||!ss||!btn) return; btn.hidden=false;\n  var on=false, rec=null;\n  function say(t){ return new Promise(function(ok){ try{ ss.cancel(); var u=new SpeechSynthesisUtterance(t); u.lang='es-AR'; u.rate=1.03; u.onend=ok; u.onerror=ok; ss.speak(u); }catch(e){ ok(); } }); }\n  function listen(){ return new Promise(function(ok){ var got='', r=new SR(); rec=r; r.lang='es-AR'; r.interimResults=false; r.continuous=false;\n    r.onresult=function(e){ for(var i=0;i<e.results.length;i++) got+=e.results[i][0].transcript+' '; };\n    r.onend=function(){ rec=null; ok(got.trim()); }; r.onerror=function(){ }; try{ r.start(); }catch(e){ ok(''); } }); }\n  function last(){ return (S.ordenes||[]).find(function(o){ return o.estado==='propuesta'; }); }\n  function wait(id){ return new Promise(function(ok){ var n=0; (function t(){ var o=(S.ordenes||[]).find(function(x){ return x.id===id; }); if((o&&o.estado!=='nueva')||++n>24) return ok(o); setTimeout(t,2500); })(); }); }\n  function setUI(){ btn.setAttribute('aria-pressed',on?'true':'false'); btn.textContent=on?'Colgar':'Llamar al jefe (voz)'; }\n  async function loop(){\n    await say('Hola Julio, soy el jefe de gabinete. Decime qué necesitás.');\n    var miss=0;\n    while(on){\n      var t=await listen(); if(!on) break;\n      if(!t){ if(++miss>=3){ await say('No te escucho. Corto. Cuando quieras, volvé a llamar.'); break; } continue; } miss=0;\n      var l=t.toLowerCase();\n      if(/\\b(chau|cort[aá]|colg[aá]|nada m[aá]s|eso es todo|listo gracias)\\b/.test(l)){ await say('Dale, chau.'); break; }\n      var p=last();\n      if(p&&/^(s[ií]|dale|ok|okey|aprob[aá]|aprobado|confirmo|hacelo|mandale)\\b/.test(l)){ try{ await S.db.doc('ordenes/'+p.id).update({estado:'aprobada',decidida:new Date().toISOString()}); await say('Aprobado. Reparto las tareas.'); }catch(e){ await say('No pude aprobar. Probá desde la pantalla.'); } continue; }\n      if(p&&/^(no\\b|rechaz|cancel|dej[aá])/.test(l)){ try{ await S.db.doc('ordenes/'+p.id).update({estado:'rechazada',decidida:new Date().toISOString()}); await say('Listo, la descarté.'); }catch(e){ await say('No pude rechazarla.'); } continue; }\n      try{\n        var r=await S.db.collection('ordenes').add({texto:t.slice(0,1500),canal:'voz'}); say('Anotado. Lo estoy pensando.');\n        var o=await wait(r.id); ss.cancel();\n        if(o&&o.estado!=='nueva'){ await say((o.resumen||'Quedó propuesta.')+' ¿Lo apruebo?'); } else { await say('Todavía lo estoy pensando. Miralo en pantalla en un ratito.'); }\n      }catch(e){ await say('No pude anotarlo. Probá de nuevo.'); }\n    }\n    on=false; setUI(); try{ ss.cancel(); }catch(e){}\n  }\n  btn.addEventListener('click',function(){ if(on){ on=false; try{ if(rec) rec.stop(); ss.cancel(); }catch(e){} setUI(); return; } on=true; setUI(); loop(); });\n})();\n\n/* Día/Noche, Tour y panel del jefe */\n(function(){\n  var d=document.documentElement, day=document.getElementById('vday'), night=document.getElementById('vnight'), tour=document.getElementById('vtour');\n  function isD(){ return d.dataset.theme==='dark'||(!d.dataset.theme&&matchMedia('(prefers-color-scheme: dark)').matches); }\n  function sync(){ day.setAttribute('aria-pressed',!isD()); night.setAttribute('aria-pressed',isD()); }\n  function set(t){ d.dataset.theme=t; try{ localStorage.setItem('oficina-tema',t); }catch(e){} sync(); }\n  try{ var t0=localStorage.getItem('oficina-tema'); if(t0) d.dataset.theme=t0; }catch(e){}\n  day.addEventListener('click',function(){ set('light'); }); night.addEventListener('click',function(){ set('dark'); }); sync();\n  var timer=null, idx=0;\n  function stop(){ if(timer){ clearInterval(timer); timer=null; } tour.setAttribute('aria-pressed','false'); }\n  tour.addEventListener('click',function(){\n    if(timer){ stop(); return; }\n    tour.setAttribute('aria-pressed','true');\n    var go=function(){ var ks=Array.from(document.querySelectorAll('#pisos .piso')).map(function(b){ return b.dataset.k; }).filter(function(k){ return k!=='all'&&k!=='meet'&&k!=='cafe'; }); if(!ks.length) return; idx=(idx+1)%ks.length; if(window.OF) window.OF.setFocus(ks[idx]); };\n    go(); timer=setInterval(go,6500);\n  });\n  document.getElementById('pisos').addEventListener('click',stop);\n  var dr=document.getElementById('drawer');\n  function open(){ dr.hidden=false; var t=document.getElementById('ordtxt'); if(t) setTimeout(function(){ t.focus(); },50); }\n  document.getElementById('jefebtn').addEventListener('click',function(){ dr.hidden?open():(dr.hidden=true); });\n  document.getElementById('drawerx').addEventListener('click',function(){ dr.hidden=true; });\n  document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&!dr.hidden) dr.hidden=true; });\n  if(location.hash==='#jefe') open();\n})();\n</script>\n</html>"
